import requests
from bs4 import BeautifulSoup
import json

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}

# 1. Statista page with canton data
print("=== Statista: Migrationshintergrund by canton ===")
url = "https://de.statista.com/statistik/daten/studie/711809/umfrage/bevoelkerungsanteil-mit-migrationshintergrund-in-der-schweiz-nach-kantonen/"
r = requests.get(url, headers=headers, timeout=15)
print(f"Status: {r.status_code}")
if r.status_code == 200:
    soup = BeautifulSoup(r.text, 'html.parser')
    # Find tables
    for table in soup.find_all('table'):
        print("\nTABLE:")
        for row in table.find_all('tr'):
            cells = [c.get_text(strip=True) for c in row.find_all(['td','th'])]
            if cells:
                print(" | ".join(cells))

    # Also look for chart data embedded in JS
    for script in soup.find_all('script'):
        if script.string and ('chart' in script.string.lower() or 'kanton' in script.string.lower() or 'genf' in script.string.lower()):
            # Look for data arrays
            import re
            # Find JSON-like data
            matches = re.findall(r'\{[^{}]*kanton[^{}]*\}', script.string, re.IGNORECASE)
            for m in matches[:5]:
                print(f"  Data: {m[:300]}")
            # Look for percentage values near canton names
            text = script.string
            for kw in ['Genf', 'Zürich', 'Basel', 'Bern', 'Tessin', 'Waadt', 'Luzern']:
                idx = text.find(kw)
                if idx >= 0:
                    print(f"  Found {kw}: ...{text[max(0,idx-20):idx+100]}...")

    # Get all text looking for canton names with percentages
    text = soup.get_text(separator='\n', strip=True)
    for line in text.split('\n'):
        if '%' in line and any(c in line for c in ['Genf', 'Zürich', 'Basel', 'Bern', 'Tessin', 'Waadt', 'Luzern', 'St. Gallen', 'Aargau', 'Zug']):
            print(f"  {line[:200]}")
